 ru={r['key']:r['ru']for r in rows if r['key'].startswith('ui.')};en={r['key']:r['en']for r in rows if r['key'].startswith('ui.')}
 titles={r['key']:r['en']for r in rows if r['key'].endswith('.title')}
 for k,(r,e)in UI.items():ru['ui.'+k]=r;en['ui.'+k]=e
 names=[('Феликс','Felix'),('Плюм','Plum'),('Марфа','Marfa'),('Семён','Semyon'),('Ника','Nika'),('Лада','Lada'),('Роза','Roza'),('Гуго','Hugo'),('Карамелька','Caramel')]
 for i,(r,e)in enumerate(names,1):ru[f'character.CH{i:02d}.name']=r;en[f'character.CH{i:02d}.name']=e
 campaign=dict(schema_version=1,unlocks_by_completion=True,chapters=[],levels=[])
 for ch in range(1,4):campaign['chapters'].append(dict(id=ch,title_key=f'ui.chapter{ch}',scene_id=f'ENV{ch:02d}',levels=[f'L{i:02d}'for i in range((ch-1)*10+1,ch*10+1)]))
 for i,c in enumerate(cards):
  lid=c['id'];prefix='level.'+lid+'.';ru[prefix+'title']=c['title_ru'];en[prefix+'title']=titles[prefix+'title']
  for key in('objective','intro'):ru[prefix+key]=c['goals_ru'];en[prefix+key]=O[i]
  for key in('joke','success'):ru[prefix+key]=c['joke_ru'];en[prefix+key]=J[i]
  for n in range(3):ru[prefix+f'hint{n+1}']=c['hints_ru'][n];en[prefix+f'hint{n+1}']=H[i][n]
  campaign['levels'].append(dict(id=lid,path=f'res://data/levels/{lid}.json',title_key=prefix+'title',scene_id=f"ENV{c['chapter']:02d}",chapter=c['chapter'],prerequisite=cards[i-1]['id']if i else None))
 extra=R/'data/authoring/extra_translations.json'
 if extra.exists():
  for k,(r,e)in json.loads(extra.read_text()).items():ru[k]=r;en[k]=e
 assert ru.keys()==en.keys()and all(ru.values())and all(en.values())
 p=R/'data/localization';p.mkdir(parents=True,exist_ok=True)
 for lang,d in(('ru',ru),('en',en)):(p/(lang+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 (R/'data/campaign.json').write_text(json.dumps(campaign,ensure_ascii=False,indent=2)+'\n');print(len(ru),'keys per language,30 levels,90 hints')
